INSERT INTO activities (slug, title, summary, body, image, image_alt, activity_date, location, is_active, sort_order) VALUES ('mentorship-session-at-lacekocot-primary-school', 'Mentorship Session at Lacekocot Primary School', 'A day of open conversation with pupils on growing up, health and confidence, including a hands-on talk on menstrual hygiene.', '<p>On 3 October 2026 our team and guest mentors visited Lacekocot Primary School for a mentorship session held on the school lawn. Mentors spoke with the pupils about growing up, health and confidence, answered their questions, and led a practical talk on menstrual hygiene for boys and girls together. The day closed with a certificate of appreciation, gift packs and a planting moment in the compound.</p><p><a href="/news/mentorship-session-at-lacekocot-primary-school">Read the full story</a> or see the photos in the <a href="/gallery">gallery</a>.</p>', 'assets/img/site/mentorship/lacekocot-0270.jpg', 'Pupils sitting on the grass in the shade of trees while mentors speak to them', '2026-10-03', 'Lacekocot Primary School', 1, 0) ON DUPLICATE KEY UPDATE title = VALUES(title), summary = VALUES(summary), body = VALUES(body), image = VALUES(image), image_alt = VALUES(image_alt), activity_date = VALUES(activity_date), location = VALUES(location);
INSERT INTO posts (post_type, slug, title, excerpt, body, cover_image, cover_alt, category, status, published_at, author_name, is_featured, seo_title, seo_description) VALUES ('news', 'mentorship-session-at-lacekocot-primary-school', 'Mentorship Session at Lacekocot Primary School', 'On 3 October 2026 our team and guest mentors spent the day with pupils of Lacekocot Primary School: open conversations about growing up, health and confidence, a hands-on talk on menstrual hygiene, and a moment of recognition and giving.', '<p class="lead">On 3 October 2026, Lumina Africa Foundation joined guest mentors at Lacekocot Primary School for a mentorship session built around one idea: young people do better when they can ask honest questions and hear honest answers from people who care.</p><figure><img src="/assets/img/site/mentorship/lacekocot-0270.jpg" alt="Pupils sitting on the grass in the shade of trees while mentors speak to them" loading="lazy"><figcaption>The mentorship session under the trees</figcaption></figure><h2>A classroom without walls</h2><p>Instead of a classroom, the session took place on the school lawn. Pupils sat in the shade of the trees in their school uniforms while the mentors and guests sat on chairs in front of them. The open setting made the conversation relaxed: pupils could see the speakers, the speakers could see every face, and nobody had to feel far from the discussion.</p><figure><img src="/assets/img/site/mentorship/lacekocot-0281.jpg" alt="Pupils in school uniform sitting on the ground and listening" loading="lazy"><figcaption>Pupils listening during the session</figcaption></figure><h2>Growing up, health and confidence</h2><p>Several mentors took turns to speak with the pupils about the changes that come with growing up, how to look after your health, and how to stay confident when you are unsure of yourself. Pupils took notes, put up their hands and, when invited, stood to answer or ask their own questions. The mentors listened as much as they spoke.</p><figure><img src="/assets/img/site/mentorship/lacekocot-0409.jpg" alt="A woman in a patterned skirt speaking to rows of seated pupils" loading="lazy"><figcaption>Speaking about growing up and health</figcaption></figure><figure><img src="/assets/img/site/mentorship/lacekocot-0461.jpg" alt="A mentor and a pupil standing facing each other during a discussion" loading="lazy"><figcaption>A pupil joins the discussion</figcaption></figure><h2>Boys and girls learning together</h2><p>One part of the day was a practical talk on menstrual hygiene. Mentors showed the pupils how sanitary products are used and cared for, and the demonstration was held with boys and girls together, so that everyone understands what is normal, why it deserves respect and how to support a classmate or sister. Packs of sanitary pads were shared with the girls of the school.</p><figure><img src="/assets/img/site/mentorship/lacekocot-0523.jpg" alt="A mentor showing a reusable pad to the pupils during the demonstration" loading="lazy"><figcaption>Showing how to use and care for pads</figcaption></figure><figure><img src="/assets/img/site/mentorship/lacekocot-0553.jpg" alt="Pupils gathered around a mentor holding a packet during the demonstration" loading="lazy"><figcaption>Boys and girls learning together</figcaption></figure><h2>Recognition and giving</h2><p>The programme also made room for thanks. A certificate of appreciation was presented, gift packs were handed over, and guests joined the pupils for a planting moment in the school compound, a small, lasting reminder of the day.</p><figure><img src="/assets/img/site/mentorship/lacekocot-0570.jpg" alt="A man holding a framed certificate while two women seated beside him smile" loading="lazy"><figcaption>A certificate of appreciation is presented</figcaption></figure><figure><img src="/assets/img/site/mentorship/lacekocot-0593.jpg" alt="Pupils and mentors gathered around a flower bed in the school compound with spades" loading="lazy"><figcaption>A planting moment in the school compound</figcaption></figure><h2>Why mentorship matters to us</h2><p>Mentorship is one of the ways Lumina Africa Foundation hopes to help young people in Northern Uganda learn, grow and thrive. Sessions like this one need only willing people and a shady tree, and they give pupils someone to look up to and somewhere to bring their questions.</p><p>Thank you to the headteacher, the teachers and the pupils of Lacekocot Primary School for welcoming us, and to every mentor and guest who gave their time.</p><figure><img src="/assets/img/site/mentorship/lacekocot-0611.jpg" alt="Pupils, teachers and mentors standing in rows in front of the school building" loading="lazy"><figcaption>Everyone together at Lacekocot Primary School</figcaption></figure><h3>Bring a mentorship session to your school</h3><p>If you lead a school, a youth group or a community and would like a mentorship session, or if you would like to volunteer as a mentor, <a href="/contact">contact us</a> or read how you can <a href="/involvement">get involved</a>. More photos are in our <a href="/gallery">gallery</a>.</p>', 'assets/img/site/mentorship/lacekocot-0270.jpg', 'Pupils sitting on the grass in the shade of trees while mentors speak to them', 'Mentorship', 'published', '2026-10-23 09:00:00', 'Lumina Africa Foundation', 1, 'Mentorship Session at Lacekocot Primary School | Lumina Africa Foundation', 'On 3 October 2026 our team and guest mentors spent the day with pupils of Lacekocot Primary School: open conversations about growing up, health and confidence, a hands-on talk on menstrual hygiene, and a moment of recognition and giving.') ON DUPLICATE KEY UPDATE title = VALUES(title), excerpt = VALUES(excerpt), body = VALUES(body), cover_image = VALUES(cover_image), cover_alt = VALUES(cover_alt), category = VALUES(category), seo_title = VALUES(seo_title), seo_description = VALUES(seo_description);
